int arr[6] = {1, 2, 4, 6, 8, 9};
int target = 14;

for (int i = 0; i < 6; i++) {
    for (int j = i + 1; j < 6; j++) {
        int currentSum = arr[i] + arr[j];
        if (currentSum == target) {
            std::cout << "Pair: " << arr[i] << ", " << arr[j] << "\n";
            return;
        }
    }
}

int arr[6] = {1, 2, 4, 6, 8, 9};
int target = 14;
int left = 0;
int right = 5;

while (left < right) {
    int currentSum = arr[left] + arr[right];
    if (currentSum == target) {
        std::cout << "Pair: " << arr[left] << ", " << arr[right] << "\n";
        return;
    }
    if (currentSum < target) {
        left++;
    } else {
        right--;
    }
}
